//! SCSS golden comparison: the expected output of `tests/fixtures-scss/*.scss` (a pure
//! CSS subset) is generated by dart-sass 1.35.2 (`scripts/style-diff/scss-oracle.cjs`),
//! asserted byte for byte here; CI does not depend on node.

use std::path::Path;

use undercoat::{Options, compile_file};

fn fixtures_dir() -> std::path::PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures-scss")
}

#[test]
fn scss_fixtures_match_dart_sass_byte_for_byte() {
    let dir = fixtures_dir();
    let mut checked = 0;
    for entry in std::fs::read_dir(&dir).expect("read fixtures") {
        let path = entry.expect("dir entry").path();
        if path.extension().and_then(|s| s.to_str()) != Some("scss") {
            continue;
        }
        let source = std::fs::read_to_string(&path).expect("read scss");
        let expected_path = path.with_extension("css");
        let expected = std::fs::read_to_string(&expected_path)
            .unwrap_or_else(|e| panic!("missing expected output {}: {e}", expected_path.display()));

        let out = compile_file(&path, &source, &Options::default())
            .unwrap_or_else(|e| panic!("{}: {e:#}", path.display()));
        assert_eq!(
            out.css,
            expected,
            "output does not match dart-sass 1.35.2: {}",
            path.display()
        );
        checked += 1;
    }
    assert!(checked >= 4, "unexpected number of fixtures: {checked}");
}
